import{_ as n,C as a,o as s,c,a3 as d,E as l,w as h,j as t,a as o}from"./chunks/framework.CCylkYel.js";const i="/screens/projects/projects_menu.png",p="/screens/projects/project_settings_menu.png",g="/screens/settings/global_channel_menu.png",u="/screens/settings/encoder_button_menu.png",j=JSON.parse('{"title":"Project","description":"","frontmatter":{},"headers":[],"relativePath":"projects/index.md","filePath":"projects/index.md"}'),m={name:"projects/index.md"};function S(f,e,b,T,_,k){const r=a("ManualRelated");return s(),c("div",null,[e[1]||(e[1]=d('<h1 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h1><p>A project is your whole setup for a set or a song: the 32 knobs and their macros, eight racks, the LFOs, the snapshots and Arrange, the tempo and the default MIDI channel.</p><h2 id="project-menu" tabindex="-1">Project menu <a class="header-anchor" href="#project-menu" aria-label="Permalink to &quot;Project menu&quot;">​</a></h2><p>Open <a href="./../navigation/main-menu">Main Menu</a> → <strong>PROJECT</strong>.</p><p><img src="'+i+'" alt="Project menu" class="screen"></p><table tabindex="0"><thead><tr><th>Row</th><th>What it does</th></tr></thead><tbody><tr><td><a href="#project-settings">PROJECT SETTINGS</a></td><td>Clock, default channel and the encoder button</td></tr><tr><td><a href="./list">LIBRARY</a></td><td>Load, create, copy or delete projects</td></tr><tr><td><strong>SAVE PROJECT</strong></td><td>Saves the open project</td></tr><tr><td><strong>RENAME PROJECT</strong></td><td>Up to 14 characters</td></tr></tbody></table><h2 id="save-your-work" tabindex="-1">Save your work <a class="header-anchor" href="#save-your-work" aria-label="Permalink to &quot;Save your work&quot;">​</a></h2><p>Changes stay in memory until you choose <strong>SAVE PROJECT</strong>. Save before you power off.</p><p>Loading another project with unsaved changes asks <strong>SAVE BEFORE SWITCHING?</strong></p><h2 id="project-settings" tabindex="-1">Project Settings <a class="header-anchor" href="#project-settings" aria-label="Permalink to &quot;Project Settings&quot;">​</a></h2><p>These belong to the open project. <strong>SAVE PROJECT</strong> keeps them.</p><p><img src="'+p+'" alt="Project Settings" class="screen"></p><h3 id="clock-settings" tabindex="-1">Clock Settings <a class="header-anchor" href="#clock-settings" aria-label="Permalink to &quot;Clock Settings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>SOURCE</strong></td><td><strong>INTERNAL</strong> runs the S32&#39;s own clock. <strong>EXTERNAL</strong> follows MIDI clock coming in. <strong>AUTO</strong> follows MIDI clock when there is one</td></tr><tr><td><strong>BPM</strong></td><td>Tempo of the internal clock, <strong>20</strong>–<strong>300</strong>. You can also set it from <a href="./../perform/edit-mode#tap-tempo">edit mode</a></td></tr><tr><td><strong>TRANSPORT</strong></td><td><strong>RUNNING</strong> or <strong>STOPPED</strong> (internal clock). Not saved with the project</td></tr></tbody></table><p>To change a value: <a href="./../navigation/controls#edit-a-value">Edit a value</a>.</p><p>Loading a project sets its clock and tempo and stops the transport.</p><h3 id="channel" tabindex="-1">Channel <a class="header-anchor" href="#channel" aria-label="Permalink to &quot;Channel&quot;">​</a></h3><p>The MIDI channel used by every macro and device set to the global channel. Change it here and they all move to the new channel. Select a channel to make it the default; a short bar marks it.</p><p><img src="'+g+'" alt="Channel 2 is the default" class="screen"></p><h3 id="encoder-button" tabindex="-1">Encoder Button <a class="header-anchor" href="#encoder-button" aria-label="Permalink to &quot;Encoder Button&quot;">​</a></h3><p>What pressing the encoder does, from any screen.</p><p><img src="'+u+'" alt="Encoder Button set to RACKS SHORTCUT" class="screen"></p><table tabindex="0"><thead><tr><th>Option</th><th>Press the encoder to…</th></tr></thead><tbody><tr><td><strong>CLOCK START/STOP</strong></td><td>Start or stop the internal clock (default)</td></tr><tr><td><strong>RACKS SHORTCUT</strong></td><td>Open the <a href="./../racks/">rack list</a></td></tr><tr><td><strong>LFOS SHORTCUT</strong></td><td>Open the <a href="./../lfos/">S32 LFOs</a></td></tr></tbody></table><p>New projects start on <strong>INTERNAL</strong> clock at <strong>120 BPM</strong>, channel <strong>1</strong>, with <strong>CLOCK START/STOP</strong>.</p>',24)),l(r,null,{default:h(()=>[...e[0]||(e[0]=[t("ul",null,[t("li",null,[t("a",{href:"./list"},"Library"),o(" — Load, create, copy or delete")]),t("li",null,[t("a",{href:"./../snapshots/"},"Snapshots"),o(" — Scenes inside a project")]),t("li",null,[t("a",{href:"./../settings/"},"Settings"),o(" — Settings for the whole S32")]),t("li",null,[t("a",{href:"./../getting-started/troubleshooting"},"Troubleshooting"),o(" — Save and storage messages")])],-1)])]),_:1})])}const C=n(m,[["render",S]]);export{j as __pageData,C as default};
